//! Peng–Robinson against `CoolProp`'s reference equations of state: the
//! accuracy a user of `PengRobinson` should expect, measured, per species and
//! state.

use anyhow::Context;
use engine_bench_physics::{
    gas::{ControlVolume, eos::PengRobinson},
    thermo::{ColdGas, Mixture, Species, SpeciesSet, gases},
    units::{
        Pressure, ThermodynamicTemperature, Volume, mass::kilogram, pressure::pascal,
        specific_heat_capacity::joule_per_kilogram_kelvin, thermodynamic_temperature::kelvin,
        volume::cubic_meter,
    },
};

/// Generated by `tools/reference/pr_reference.py`: species, T K, p Pa,
/// reference Z.
#[allow(clippy::unreadable_literal, reason = "generated golden values")]
const REFERENCE_Z: [(&str, f64, f64, f64, f64); 20] = [
    ("N2", 300.0, 10000000.0, 1.0052108750748905, 0.04),
    ("N2", 300.0, 30000000.0, 1.1429587844442939, 0.06),
    ("N2", 200.0, 10000000.0, 0.8446746700766719, 0.04),
    ("N2", 150.0, 30000000.0, 1.0823036682360887, 0.11),
    ("O2", 300.0, 10000000.0, 0.9532870714039035, 0.04),
    ("O2", 300.0, 30000000.0, 0.9892306433810705, 0.04),
    ("O2", 200.0, 10000000.0, 0.6930848979855869, 0.04),
    ("O2", 150.0, 30000000.0, 0.8134464586695337, 0.11),
    ("Ar", 300.0, 10000000.0, 0.9555563649064747, 0.04),
    ("Ar", 300.0, 30000000.0, 0.9956125640172572, 0.04),
    ("Ar", 200.0, 10000000.0, 0.7112897354682945, 0.04),
    ("Ar", 150.0, 30000000.0, 0.8374705048215824, 0.11),
    ("He", 300.0, 10000000.0, 1.0469080203761487, 0.04),
    ("He", 300.0, 30000000.0, 1.1377772731489422, 0.04),
    ("He", 200.0, 10000000.0, 1.0724242753378235, 0.04),
    ("He", 150.0, 30000000.0, 1.2864784868425927, 0.06),
    ("CO2", 300.0, 5000000.0, 0.6870720297756068, 0.04),
    ("CO2", 350.0, 20000000.0, 0.49247220372163847, 0.06),
    ("CO2", 400.0, 10000000.0, 0.8192318807579384, 0.04),
    ("CO2", 350.0, 5000000.0, 0.8437487878915616, 0.04),
];

/// Oxygen alone, with the cold-gas set's 60 K floor (its vibration is frozen
/// there too).
#[derive(Debug, Clone, Copy, PartialEq)]
struct Oxygen;

impl SpeciesSet<1> for Oxygen {
    const SPECIES: [&'static Species; 1] = [&gases::O2];
    const TEMPERATURE_RANGE: (f64, f64) = (60.0, 6000.0);
}

/// Z of pure `name` from a Peng–Robinson tank filled to (p, T).
fn pure_z(name: &str, p: f64, t: f64) -> anyhow::Result<f64> {
    if name == "O2" {
        return tank_z(Mixture::<Oxygen, 1>::from_mass_fractions([1.0])?, p, t);
    }
    let i = ColdGas::SPECIES
        .iter()
        .position(|s| s.name() == name)
        .with_context(|| format!("{name} is not a cold-gas propellant"))?;
    let mut y = [0.0; 4];
    y[i] = 1.0;
    tank_z(Mixture::<ColdGas, 4>::from_mass_fractions(y)?, p, t)
}

/// Z from a Peng–Robinson tank filled to (p, T): the stored mass gives v.
fn tank_z<S, const N: usize>(mixture: Mixture<S, N>, p: f64, t: f64) -> anyhow::Result<f64>
where
    S: SpeciesSet<N>,
{
    let cv = ControlVolume::with_eos(
        PengRobinson::<S, N>::new()?,
        mixture,
        Pressure::new::<pascal>(p),
        ThermodynamicTemperature::new::<kelvin>(t),
        Volume::new::<cubic_meter>(1.0),
    )?;
    let r = mixture.gas_constant().get::<joule_per_kilogram_kelvin>();
    Ok(p / (cv.mass().get::<kilogram>() * r * t))
}

#[test]
fn test_peng_robinson_compressibility_is_within_its_known_accuracy() -> anyhow::Result<()> {
    // Standard PR overpredicts density: 1-4 % up to ~100 bar, up to 5.5 %
    // dense or near-critical, ~10 % for N2, O2 and Ar at 150 K and 300 bar.
    for (name, t, p, z_ref, tolerance) in REFERENCE_Z {
        let z = pure_z(name, p, t)?;
        let error = z / z_ref - 1.0;
        anyhow::ensure!(
            error.abs() < tolerance,
            "{name} at {t} K, {p} Pa: Z = {z} vs {z_ref} ({error:+.3})"
        );
    }
    Ok(())
}
